from __future__ import annotations

import math


def password_strength_score(password: str) -> float:
    if not password:
        return 0.0
    classes = 0
    if any(c.islower() for c in password):
        classes += 1
    if any(c.isupper() for c in password):
        classes += 1
    if any(c.isdigit() for c in password):
        classes += 1
    if any(not c.isalnum() for c in password):
        classes += 1
    alphabet = 26 * (classes > 0) + 26 * (classes > 1) + 10 * (classes > 2) + 32 * (classes > 3)
    alphabet = max(1.0, float(alphabet))
    return math.log2(alphabet) * len(password)
